const body = $input.first().json.body || $input.first().json;
const project_id = (body.project_id || '').trim();
const script_ids = body.script_ids || [];
const source = (body.source || 'pm_comments').trim();
const manual_notes = (body.manual_notes || '').trim();

if (!project_id) throw new Error('project_id is required');

return [{ json: { project_id, script_ids, source, manual_notes } }];

const payload = $('Extract Revision Payload').first().json;
const rawProject = $('Fetch Project').first().json;
const project = rawProject.fields ? { id: rawProject.id, ...rawProject.fields } : rawProject;

const rawScripts = $input.first().json.records || [];
let scripts = rawScripts.map(r => ({ id: r.id, ...r.fields }));

// Filter by script_ids if provided
if (payload.script_ids && payload.script_ids.length > 0) {
  scripts = scripts.filter(s => payload.script_ids.includes(s.id));
}

// Only revise scripts that have google_doc_id
scripts = scripts.filter(s => s.google_doc_id);

if (scripts.length === 0) {
  throw new Error('No scripts with google_doc_id found for revision');
}

return scripts.map(s => ({ json: {
  ...payload,
  project,
  script: s,
  brand_name: project.brand_name || 'Brand'
}}));

const data = $('Merge Context').item;
const d = data.json;
const script = d.script;
const comments = $input.first().json.comments || [];
const unresolvedComments = comments.filter(c => !c.resolved);
const manualNotes = d.manual_notes || '';

// Build feedback section
let feedback = '';
unresolvedComments.forEach((c, i) => {
  const quoted = c.quotedFileContent?.value || '';
  feedback += `[${i+1}] On "${quoted}": "${c.content}" — ${c.author?.displayName || 'Reviewer'}\n`;
});
if (manualNotes) {
  feedback += `\n[Manual Notes]: "${manualNotes}"\n`;
}

if (!feedback.trim() && !manualNotes) {
  feedback = 'No specific comments found. Please review and improve the script quality overall.';
}

const prompt = `You are revising an existing UGC script based on feedback.

== CURRENT SCRIPT ==
Concept: ${script.concept_name || 'N/A'}
Hook: ${script.hook_1 || script.hook || 'N/A'}
Full Script: ${script.full_script || 'N/A'}
Creative Table: ${script.creative_table_json || '[]'}

== FEEDBACK COMMENTS ==
${feedback}

== INSTRUCTIONS ==
1. Address EVERY comment listed above
2. Preserve the overall concept, hook style, and format
3. Only change what the feedback specifically asks for
4. Keep the same structure and flow
5. Return the COMPLETE revised script in this JSON format:

\`\`\`json
{
  "hook_1": "revised main hook",
  "hook_2": "revised alternative hook",
  "hook_3": "revised third hook",
  "full_script": "complete revised script text",
  "creative_table": [
    { "voiceover": "...", "visuals": "...", "references": "..." }
  ],
  "revision_summary": "Brief summary of what was changed and why"
}
\`\`\`

Output ONLY valid JSON.`;

const commentIds = unresolvedComments.map(c => c.id);

return [{ json: {
  ...d,
  revision_prompt: prompt,
  comment_ids: commentIds,
  comment_count: unresolvedComments.length
}}];

const d = $input.first().json;
const body = {
  systemInstruction: { parts: [{ text: 'You are an expert UGC script writer. Revise scripts based on feedback while preserving the creative direction.' }] },
  contents: [{ role: 'user', parts: [{ text: d.revision_prompt }] }],
  generationConfig: { temperature: 0.4, maxOutputTokens: 4096 }
};
return [{ json: { ...d, gemini_body: JSON.stringify(body) } }];

const d = $('Build Revision Prompt').item.json;
const raw = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text || '';

let cleanOutput = raw
  .replace(/<thinking>[\s\S]*?<\/thinking>/gi, '')
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/g, '')
  .trim();

let revised;
try {
  revised = JSON.parse(cleanOutput);
} catch(e) {
  const match = cleanOutput.match(/\{[\s\S]*\}/);
  if (match) {
    try { revised = JSON.parse(match[0]); } catch(e2) {
      revised = { full_script: d.script.full_script, revision_summary: 'Failed to parse revision' };
    }
  } else {
    revised = { full_script: d.script.full_script, revision_summary: 'Failed to parse revision' };
  }
}

const currentVersion = parseInt(d.script.version) || 1;

return [{ json: {
  script_id: d.script.id,
  google_doc_id: d.script.google_doc_id,
  project_id: d.project_id,
  brand_name: d.brand_name,
  concept_name: d.script.concept_name || 'Script',
  script_number: d.script.script_number || 0,
  source: d.source,
  comment_ids: d.comment_ids,
  comment_count: d.comment_count,
  new_version: currentVersion + 1,
  hook_1: revised.hook_1 || d.script.hook_1 || '',
  hook_2: revised.hook_2 || d.script.hook_2 || '',
  hook_3: revised.hook_3 || d.script.hook_3 || '',
  full_script: revised.full_script || d.script.full_script || '',
  creative_table_json: revised.creative_table ? JSON.stringify(revised.creative_table) : (d.script.creative_table_json || '[]'),
  revision_notes: revised.revision_summary || 'Script revised based on feedback'
}}];

// Build HTTP requests to resolve each comment
const d = $input.first().json;
const commentIds = d.comment_ids || [];
const docId = d.google_doc_id;

// Return items for each comment to resolve
if (commentIds.length === 0) return [{ json: d }];

const items = commentIds.map(cId => ({
  json: {
    ...d,
    resolve_url: `https://www.googleapis.com/drive/v3/files/${docId}/comments/${cId}`,
    resolve_body: JSON.stringify({ resolved: true })
  }
}));
return items;
